def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.I = pyo.Set(initialize=d["products"], ordered=True)

    # Decision variables: integer number of units of each product
    # Lower bound 0 (products sold cannot be negative); explicit min/max handled by constraints.
    model.x = pyo.Var(model.I, within=pyo.NonNegativeIntegers)

    # Objective: maximise total profit
    def obj_rule(m):
        return sum(d["profit"][i] * m.x[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Each product must meet its minimum required volume
    def min_rule(m, i):
        return m.x[i] >= d["min_units"][i]

    model.min_units = pyo.Constraint(model.I, rule=min_rule)

    # Each product cannot exceed its maximum production cap
    def max_rule(m, i):
        return m.x[i] <= d["max_units"][i]

    model.max_units = pyo.Constraint(model.I, rule=max_rule)

    # Total number of items combined cannot exceed the total shipping/making limit
    def total_rule(m):
        return sum(m.x[i] for i in m.I) <= d["max_total_items"]

    model.total_items = pyo.Constraint(rule=total_rule)

    return model

import pyomo.environ as pyo

DATA = {
