    "max_qty": {"coffee": 60, "chocolate": 35},
    "max_total": 75,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["products"])

    def bounds_rule(m, i):
        return (d["min_qty"][i], d["max_qty"][i])

    model.x = pyo.Var(model.I, within=pyo.NonNegativeIntegers, bounds=bounds_rule)

    def obj_rule(m):
        return sum(d["profit"][i] * m.x[i] for i in m.I)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.maximize)

    # Minimum demand: each product must be at least its minimum
    def min_rule(m, i):
        return m.x[i] >= d["min_qty"][i]

    model.min_demand = pyo.Constraint(model.I, rule=min_rule)

    # Maximum demand: each product at most its maximum
    def max_rule(m, i):
        return m.x[i] <= d["max_qty"][i]

    model.max_demand = pyo.Constraint(model.I, rule=max_rule)

    # Total items cannot exceed 75
    def total_rule(m):
        return sum(m.x[i] for i in m.I) <= d["max_total"]

    model.total_items = pyo.Constraint(rule=total_rule)

    return model


